func errStr(err error) string {
	if err == nil {
		return "<nil>"
	}
	return err.Error()
}

func main() {
	for _, c := range []struct {
		name string
		data []byte
	}{
		{"trunc10", c_trunc10},
		{"trunc100", c_trunc100},
		{"badmagic", c_badmagic},
		{"notbz2", c_notbz2},
		{"bitflip", c_bitflip},
	} {
		r := bzip2.NewReader(bytes.NewReader(c.data))
		out, err := io.ReadAll(r)
		fmt.Printf("%s uneof=%v err=%q outlen=%d\n",
			c.name, err == io.ErrUnexpectedEOF, errStr(err), len(out))
	}
	// empty input.
	r := bzip2.NewReader(bytes.NewReader(nil))
	_, err := io.ReadAll(r)
	fmt.Println("empty err", errStr(err))
}
